pgp_set_blob(pgp_blob_t *blob, const u8 *data, size_t len)
{
        if (blob->data)
                free(blob->data);
        blob->data = NULL;
        blob->len    = 0;
        blob->status = 0;

        if (len > 0) {
                void *tmp = calloc(len, 1);

                if (tmp == NULL)
                        return SC_ERROR_OUT_OF_MEMORY;

                blob->data = tmp;
                blob->len  = (unsigned int)len;
                if (data != NULL)
                        memcpy(blob->data, data, len);
        }

        if (blob->file)
                blob->file->size = len;

        return SC_SUCCESS;
}


